describe('Search Filter - No Results Message', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').should('be.visible');
  });

  it('should display "No results" message when search returns no matches', () => {
    cy.get('[data-testid="search-input"]').type('nonexistentitem12345');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .and('contain', 'No results');

    cy.get('[data-testid="results-list"]')
      .should('not.exist');
  });

  it('should display results when search matches items', () => {
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="results-list"]')
      .should('be.visible');

    cy.get('[data-testid="no-results-message"]')
      .should('not.exist');

    cy.get('[data-testid="result-item"]')
      .should('have.length.greaterThan', 0);
  });

  it('should show "No results" message when clearing search that previously had results', () => {
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="result-item"]')
      .should('have.length.greaterThan', 0);

    cy.get('[data-testid="search-input"]').clear();
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .and('contain', 'No results');
  });

  it('should handle special characters in search without crashing', () => {
    cy.get('[data-testid="search-input"]').type('!@#$%^&*()');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible');

    cy.get('[data-testid="error-message"]')
      .should('not.exist');
  });

  it('should display "No results" for whitespace-only search', () => {
    cy.get('[data-testid="search-input"]').type('   ');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible');
  });

  it('should transition from results to no results when filtering narrows results to zero', () => {
    cy.get('[data-testid="search-input"]').type('a');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="result-item"]')
      .should('have.length.greaterThan', 0);

    cy.get('[data-testid="search-input"]').clear();
    cy.get('[data-testid="search-input"]').type('azbycxdwevfugthsirjqkplomn');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .and('contain', 'No results');

    cy.get('[data-testid="results-list"]')
      .should('not.exist');
  });
});
